fn local_provision(cwd: &Path, module: &str) -> JsonValue {
    serde_json::from_slice(
        &fs::read(
            cwd.join(".unicodex/foreign-process/provisions")
                .join(format!("{module}.json")),
        )
        .unwrap(),
    )
    .unwrap()
}

fn cid<'a>(value: &'a JsonValue, key: &str) -> &'a str {
    value[key].as_str().unwrap()
}
fn cid_at(value: &JsonValue, path: &[&str]) -> String {
    path.iter()
        .fold(value, |current, field| &current[*field])
        .as_str()
        .unwrap()
        .to_owned()
}

